@app.get('/api/tax-returns/{year}/file')
def get_tax_filing_pdf(
    year: int,
    filing_id: int = Query(...),
    session: Session = Depends(get_session),
    user: User = Depends(get_current_user)
):
    filing = session.exec(
        select(TaxFiling).where(
            TaxFiling.id == filing_id,
            TaxFiling.tax_year == year,
            TaxFiling.taxpayer_user_id == user.id
        )
    ).first()
    if not filing or not os.path.exists(filing.form_pdf_path):
        raise HTTPException(status_code=404, detail="Tax filing document not found")

    return FileResponse(path=filing.form_pdf_path, filename=f"TaxReturn_{year}_{filing_id}.pdf")
